//! A running node leaves the finality signer alone (#350, B6; the owner's
//! narrowing of the finality crate's dormancy guard, 2026-11-09): `sumchain
//! run`, as a producing validator, neither initializes signer state nor
//! produces a finality signature.
//!
//! The real binary runs a one-validator NONPRODUCTION devnet (chain id 1337,
//! a key generated by the binary into a temp directory) until it has produced
//! blocks, and is stopped with SIGTERM:
//!
//! * with no signer: no `<data-dir>/finality` directory and no mirror record
//!   appear, and `signer status` finds nothing initialized;
//! * with a signer initialized between two runs (`sumchain signer init`, with
//!   the public key): after the second run every signer file and the mirror
//!   record are byte for byte, and modification time for modification time,
//!   as initialized, and `signer status` reports no persist and no signature.
#![cfg(unix)]

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Output, Stdio};
use std::time::{Duration, Instant, SystemTime};

use sumchain_storage::certified_meta::SIGNER_MIRROR_KEY;
use sumchain_storage::{cf, Database};

const BIN: &str = env!("CARGO_BIN_EXE_sumchain");

struct Devnet {
    dir: tempfile::TempDir,
    pubkey: String,
}

impl Devnet {
    fn data(&self) -> PathBuf {
        self.dir.path().join("data")
    }
    fn genesis(&self) -> PathBuf {
        self.dir.path().join("genesis.json")
    }
}

fn devnet() -> Devnet {
    let dir = tempfile::tempdir().unwrap();
    let p = dir.path();
    let key = p.join("fixture-validator.json");
    let out = Command::new(BIN)
        .args(["keygen", "--output"])
        .arg(&key)
        .output()
        .unwrap();
    assert!(out.status.success(), "keygen failed: {out:?}");
    let pubkey = String::from_utf8_lossy(&out.stdout)
        .lines()
        .find_map(|l| l.strip_prefix("Public key: ").map(str::to_owned))
        .expect("keygen prints the public key");
    let now = SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_millis();
    fs::write(
        p.join("genesis.json"),
        format!(
            r#"{{"chain_id":1337,"genesis_time":{now},"validators":["{pubkey}"],"alloc":{{}},
 "params":{{"block_time_ms":1000,"max_block_bytes":1000000,"max_txs_per_block":1000,"min_fee":1}}}}"#
        ),
    )
    .unwrap();
    // Every listener binds port 0; the test reads the log and signals the
    // process, and never connects.
    fs::write(
        p.join("node.toml"),
        format!(
            r#"[node]
genesis = "{g}"
data_dir = "{d}"
validator_key = "{k}"
[consensus]
engine = "poa"
[network]
listen_addr = "/ip4/127.0.0.1/tcp/0"
mdns = false
[rpc]
addr = "127.0.0.1:0"
[health]
addr = "127.0.0.1:0"
[logging]
level = "info"
json = false
"#,
            g = p.join("genesis.json").display(),
            d = p.join("data").display(),
            k = key.display(),
        ),
    )
    .unwrap();
    Devnet { dir, pubkey }
}

/// `sumchain run` until it has produced `blocks` blocks, then SIGTERM; it
/// must exit cleanly.
fn run_until_produced(net: &Devnet, run: &str, blocks: usize) {
    let log = net.dir.path().join(format!("{run}.log"));
    let f = fs::File::create(&log).unwrap();
    let mut child = Command::new(BIN)
        .args(["run", "--config"])
        .arg(net.dir.path().join("node.toml"))
        .env("NO_COLOR", "1")
        .stdout(Stdio::from(f.try_clone().unwrap()))
        .stderr(Stdio::from(f))
        .spawn()
        .unwrap();
    let text = || fs::read_to_string(&log).unwrap_or_default();
    let t = Instant::now();
    while text().matches("Produced block").count() < blocks {
        if let Some(st) = child.try_wait().unwrap() {
            panic!("{run}: the node exited ({st}) early; log:\n{}", text());
        }
        if t.elapsed() > Duration::from_secs(90) {
            let _ = child.kill();
            panic!(
                "{run}: fewer than {blocks} blocks produced; log:\n{}",
                text()
            );
        }
        std::thread::sleep(Duration::from_millis(200));
    }
    let st = Command::new("kill")
        .arg("-TERM")
        .arg(child.id().to_string())
        .status()
        .unwrap();
    assert!(st.success());
    let t = Instant::now();
    let status = loop {
        if let Some(st) = child.try_wait().unwrap() {
            break st;
        }
        if t.elapsed() > Duration::from_secs(30) {
            let _ = child.kill();
            panic!("{run}: no exit after SIGTERM; log:\n{}", text());
        }
        std::thread::sleep(Duration::from_millis(100));
    };
    assert!(status.success(), "{run}: {status}; log:\n{}", text());
}

fn signer(net: &Devnet, args: &[&str]) -> Output {
    Command::new(BIN)
        .arg("signer")
        .args(args)
        .args(["--data-dir", net.data().to_str().unwrap()])
        .args(["--genesis", net.genesis().to_str().unwrap()])
        .output()
        .unwrap()
}

fn text(out: &Output) -> String {
    format!(
        "{}{}",
        String::from_utf8_lossy(&out.stdout),
        String::from_utf8_lossy(&out.stderr)
    )
}

/// Every file of the signer directory: contents and modification time.
fn signer_files(data: &Path) -> Option<BTreeMap<String, (Vec<u8>, SystemTime)>> {
    let entries = fs::read_dir(data.join("finality")).ok()?;
    Some(
        entries
            .map(|e| {
                let e = e.unwrap();
                let meta = e.metadata().unwrap();
                (
                    e.file_name().to_string_lossy().into_owned(),
                    (fs::read(e.path()).unwrap(), meta.modified().unwrap()),
                )
            })
            .collect(),
    )
}

fn mirror(data: &Path) -> Option<Vec<u8>> {
    Database::open_read_only(data)
        .unwrap()
        .get(cf::META, SIGNER_MIRROR_KEY)
        .unwrap()
}

#[test]
fn a_producing_validator_neither_initializes_nor_signs() {
    let net = devnet();

    run_until_produced(&net, "first", 2);
    assert_eq!(signer_files(&net.data()), None, "no signer directory");
    assert_eq!(mirror(&net.data()), None, "no mirror record");
    let out = signer(&net, &["status"]);
    assert_eq!(out.status.code(), Some(3), "{}", text(&out));

    let out = signer(&net, &["init", "--validator-pubkey", &net.pubkey]);
    assert!(out.status.success(), "{}", text(&out));
    let files = signer_files(&net.data()).expect("initialized");
    let record = mirror(&net.data()).expect("the mirror record");
    assert_eq!(files["signer.v1"].0, record);

    run_until_produced(&net, "second", 2);
    assert_eq!(
        signer_files(&net.data()).as_ref(),
        Some(&files),
        "the run left every signer file as initialized"
    );
    assert_eq!(mirror(&net.data()), Some(record), "and the mirror record");
    let out = signer(&net, &["status"]);
    assert_eq!(out.status.code(), Some(0), "{}", text(&out));
    let t = text(&out);
    assert!(t.contains("Persists:         0"), "{t}");
    assert!(t.contains("Last signature:   none"), "{t}");
}
